/**
 * Interface language. The source text is Simplified Chinese; the other languages are tables keyed by that
 * text (generated by scripts/i18n-extract.mjs). Keys with {0}, {1}… are patterns for text built from
 * template strings.
 */
export type Locale = 'zh-CN' | 'zh-TW' | 'en';
export const locales: Array<{ id: Locale; label: string }> = [
  { id: 'zh-CN', label: '简体中文' },
  { id: 'zh-TW', label: '繁體中文' },
  { id: 'en', label: 'English' },
];
export const isLocale = (value: unknown): value is Locale => locales.some((locale) => locale.id === value);

/** The language to start in when the user has not chosen one: the system's, mapped to ours. */
export function defaultLocale(languages: readonly string[]): Locale {
  for (const language of languages.map((value) => value.toLowerCase())) {
    if (/^zh-(tw|hk|mo|hant)/.test(language)) return 'zh-TW';
    if (language.startsWith('zh')) return 'zh-CN';
    if (language.startsWith('en')) return 'en';
  }
  return 'zh-CN';
}

const cjk = /[㐀-鿿]/;
export const normalize = (text: string) => text.replace(/\s+/g, ' ').trim();
const escape = (text: string) => text.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

export type Translate = (text: string) => string | undefined;

/** Builds a lookup for one table: exact keys first, then patterns (more literal text first). */
export function createTranslator(table: Record<string, string>, keep?: ReadonlySet<string>): Translate {
  const isEnglish = Object.values(table).some((value) => /[A-Za-z]/.test(value) && !cjk.test(value));
  const exact = new Map<string, string>();
  const patterns: Array<{
    pattern: RegExp;
    output: string;
    literal: number;
    groups: number;
    quoted: Set<number>;
    spacePairs: Array<[number, number]>;
    allowForPiece: boolean;
  }> = [];
  for (const [key, value] of Object.entries(table)) {
    if (!/\{\d+\}/.test(key)) {
      exact.set(key, value);
      continue;
    }
    const parts = key.split(/(\{\d+\})/);
    // Each placeholder becomes a numbered group, so {1} may come before {0} in the source.
    const groups: number[] = [];
    const quoted = new Set<number>();
    const spacePairs: Array<[number, number]> = [];
    const source = parts
      .map((part, partIndex) => {
        const slot = part.match(/^\{(\d+)\}$/);
        if (!slot) return escape(part);
        const groupIndex = groups.length;
        const slotNumber = Number(slot[1]);
        groups.push(slotNumber);
        const prev = parts[partIndex - 1] ?? '';
        const next = parts[partIndex + 1] ?? '';
        if ((prev.endsWith('「') && next.startsWith('」')) || (prev.endsWith('“') && next.startsWith('”'))) {
          quoted.add(groupIndex);
        }
        if (prev === ' ' && /^\{(\d+)\}$/.test(parts[partIndex - 2] ?? '')) {
          spacePairs.push([groupIndex - 1, groupIndex]);
        }
        return '(.+?)';
      })
      .join('');
    const literalText = key.replace(/\{\d+\}/g, '').trim();
    const allowForPiece = literalText.length >= 2 && !/^[㐀-鿿]{1,3}\s*\{\d+\}$/.test(key);
    patterns.push({
      pattern: new RegExp(`^${source}$`, 's'),
      output: value.replace(/\{(\d+)\}/g, (_, slot: string) => `{@${groups.indexOf(Number(slot))}}`),
      literal: key.replace(/\{\d+\}/g, '').length,
      groups: groups.length,
      quoted,
      spacePairs,
      allowForPiece,
    });
  }
  patterns.sort((a, b) => b.literal - a.literal || a.groups - b.groups);
  const leftover = (text: string) => (text.match(/[㐀-鿿]/g) ?? []).length;

  const translateListItem = (item: string): string => {
    const trimmed = normalize(item);
    if (!trimmed || !cjk.test(trimmed)) return trimmed;
    const direct = translatePiece(trimmed, false);
    if (!cjk.test(direct)) return direct;
    const numbered = /^(.+?)\s+(\d+)$/.exec(trimmed);
    if (numbered && numbered[1]!.length >= 3) {
      const base = exact.get(numbered[1]!);
      if (base !== undefined) return `${base} ${numbered[2]}`;
    }
    return direct;
  };

  const translateRuleCandidate = (candidate: string): string => {
    const trimmed = normalize(candidate);
    if (!trimmed || !cjk.test(trimmed)) return trimmed;
    const parts = trimmed.split(/(?<! )·(?! )/);
    return parts.map((part) => translateSingle(part) ?? part).join('·');
  };

  const translatePiece = (rawPiece: string, isQuoted: boolean): string => {
    const piece = normalize(rawPiece);
    if (!piece) return rawPiece;
    if (isQuoted) return rawPiece;
    const hit = exact.get(piece);
    if (hit !== undefined) return hit;
    if (!isQuoted && piece.includes('、')) {
      return piece
        .split('、')
        .map((item) => translateListItem(item))
        .join(isEnglish ? ', ' : '、');
    }
    if (!isQuoted && piece.includes(' ／ ')) {
      return piece
        .split(' ／ ')
        .map((item) => translateRuleCandidate(item))
        .join(isEnglish ? ' / ' : ' ／ ');
    }
    if (!cjk.test(piece)) return isEnglish ? piece : rawPiece;
    const patterned = translateWhole(piece, true);
    if (patterned !== undefined && !cjk.test(patterned)) return patterned;
    if (piece.includes('：')) {
      const colonIndex = piece.indexOf('：');
      const left = piece.slice(0, colonIndex).trim();
      const right = piece.slice(colonIndex + 1).trim();
      if (left && right) {
        const tLeft = (left !== '设置' ? translateWhole(left, false) : undefined) ?? left;
        const tRight = translateSingle(right) ?? right;
        if (tLeft !== left || tRight !== right) {
          return `${tLeft}${isEnglish ? ': ' : '：'}${tRight}`;
        }
      }
    }
    if (patterned !== undefined) return patterned;
    return isEnglish ? piece : rawPiece;
  };

  const translateWhole = (value: string, forPiece = false): string | undefined => {
    const hit = exact.get(value);
    if (hit !== undefined) return hit;
    for (const { pattern, output, quoted, spacePairs, allowForPiece } of patterns) {
      if (forPiece && !allowForPiece) continue;
      const match = pattern.exec(value);
      if (!match) continue;
      const captures = match.slice(1).map((item) => item ?? '');
      for (const [leftIndex, rightIndex] of spacePairs) {
        if (quoted.has(leftIndex) || quoted.has(rightIndex)) continue;
        const combined = `${captures[leftIndex]} ${captures[rightIndex]}`;
        const spaces: number[] = [];
        for (let i = 0; i < combined.length; i++) {
          if (combined[i] === ' ') spaces.push(i);
        }
        if (spaces.length <= 1) continue;
        let bestLeft = captures[leftIndex]!;
        let bestRight = captures[rightIndex]!;
        let bestScore =
          leftover(translatePiece(bestLeft, false)) +
          leftover(translatePiece(bestRight, false)) -
          (translatePiece(bestRight, false) !== normalize(bestRight) ? 0.5 : 0);
        for (const pos of spaces.slice(1)) {
          const candLeft = combined.slice(0, pos);
          const candRight = combined.slice(pos + 1);
          if (!candLeft || !candRight) continue;
          const tLeft = translatePiece(candLeft, false);
          const tRight = translatePiece(candRight, false);
          const score = leftover(tLeft) + leftover(tRight) - (tRight !== normalize(candRight) ? 0.5 : 0);
          if (score < bestScore) {
            bestScore = score;
            bestLeft = candLeft;
            bestRight = candRight;
          }
        }
        captures[leftIndex] = bestLeft;
        captures[rightIndex] = bestRight;
      }
      // Pieces filled into a pattern are translated too when they are known interface text.
      return output.replace(/\{@(\d+)\}/g, (_, index: string) => {
        const groupIndex = Number(index);
        const piece = captures[groupIndex] ?? '';
        return keep?.has(piece.trim()) ? piece : translatePiece(piece, quoted.has(groupIndex));
      });
    }
    return undefined;
  };

  const translateSingle = (text: string): string | undefined => {
    const value = keep ? text.trim() : normalize(text);
    if (!value || !cjk.test(value)) return undefined;
    const direct = table[value];
    if (direct !== undefined) return direct;
    let whole = translateWhole(value, false);
    if (value.includes('：')) {
      const colonIndex = value.indexOf('：');
      const left = value.slice(0, colonIndex).trim();
      const right = value.slice(colonIndex + 1).trim();
      if (left && right) {
        const tLeft = (!keep?.has(left) && left !== '设置' ? translateWhole(left, false) : undefined) ?? left;
        const tRight = translateSingle(right) ?? right;
        if (tLeft !== left || tRight !== right) {
          const colonJoined = `${tLeft}${isEnglish ? ': ' : '：'}${tRight}`;
          if (keep?.has(left) || whole === undefined || (cjk.test(whole) && leftover(colonJoined) < leftover(whole))) {
            whole = colonJoined;
          }
        }
      }
    }
    if (!value.includes(' · ')) return whole;
    // Status lines are joined from pieces ("就绪 · 5 次任务"): translate piece by piece, and keep whichever
    // reading leaves less untranslated text.
    const protectedNames = [...(keep ?? [])]
      .filter((name) => name.includes(' · '))
      .sort((a, b) => b.length - a.length)
      .map(escape);
    const separators = new RegExp(['「[^」]*」', '“[^”]*”', ...protectedNames, ' · '].join('|'), 'g');
    const pieces: string[] = [];
    let start = 0;
    for (const match of value.matchAll(separators)) {
      if (match[0] !== ' · ') continue;
      pieces.push(value.slice(start, match.index));
      start = match.index + match[0].length;
    }
    pieces.push(value.slice(start));
    const translated = pieces.map((piece) => (keep?.has(piece.trim()) ? undefined : translateWhole(piece, false)));
    if (!translated.some((piece) => piece !== undefined)) return whole;
    const joined = pieces.map((piece, index) => translated[index] ?? piece).join(' · ');
    return whole === undefined || leftover(joined) < leftover(whole) || pieces.some((piece) => exact.has(piece))
      ? joined
      : whole;
  };

  const translateLine = (line: string): string | undefined => {
    const bullet = /^(\s*-\s+)(.+)$/.exec(line);
    if (bullet) {
      const inner = translateSingle(bullet[2]!);
      return inner !== undefined ? `${bullet[1]}${inner}` : undefined;
    }
    return translateSingle(line);
  };

  const translate: Translate = (text) => {
    const single = translateSingle(text);
    if (single !== undefined && !cjk.test(single)) return single;
    if (text.includes('\n')) {
      const lines = text.split('\n');
      const translatedLines = lines.map((line) => translateLine(line));
      if (translatedLines.some((line) => line !== undefined)) {
        return lines.map((line, index) => translatedLines[index] ?? line).join('\n');
      }
    }
    return single;
  };

  return translate;
}

/**
 * Keeps the original's leading and trailing spaces around a translated text node. A label ending in a
 * full-width colon (预计耗时：) needs no space before the value in the next node; its English colon does.
 */
export function withSpacing(original: string, translated: string): string {
  const lead = original.match(/^\s*/)?.[0] ?? '';
  const trail = original.match(/\s*$/)?.[0] ?? '';
  const colon = original.endsWith('：') && translated.endsWith(':');
  return `${lead ? ' ' : ''}${translated}${trail || colon ? ' ' : ''}`;
}
